// UpdatedByGTE applies the GTE predicate on the "updated_by" field.
func UpdatedByGTE(v int64) predicate.OperatorSiteSetting {
	return predicate.OperatorSiteSetting(sql.FieldGTE(FieldUpdatedBy, v))
}

// UpdatedByLT applies the LT predicate on the "updated_by" field.
func UpdatedByLT(v int64) predicate.OperatorSiteSetting {
	return predicate.OperatorSiteSetting(sql.FieldLT(FieldUpdatedBy, v))
}

// UpdatedByLTE applies the LTE predicate on the "updated_by" field.
func UpdatedByLTE(v int64) predicate.OperatorSiteSetting {
	return predicate.OperatorSiteSetting(sql.FieldLTE(FieldUpdatedBy, v))
}

// HasOperator applies the HasEdge predicate on the "operator" edge.
func HasOperator() predicate.OperatorSiteSetting {
	return predicate.OperatorSiteSetting(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, OperatorTable, OperatorColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOperatorWith applies the HasEdge predicate on the "operator" edge with a given conditions (other predicates).
func HasOperatorWith(preds ...predicate.Operator) predicate.OperatorSiteSetting {
	return predicate.OperatorSiteSetting(func(s *sql.Selector) {
		step := newOperatorStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OperatorSiteSetting) predicate.OperatorSiteSetting {
	return predicate.OperatorSiteSetting(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OperatorSiteSetting) predicate.OperatorSiteSetting {
	return predicate.OperatorSiteSetting(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OperatorSiteSetting) predicate.OperatorSiteSetting {
	return predicate.OperatorSiteSetting(sql.NotPredicates(p))
}
